/**
 * API tokens, private keys and service-account JSON must never be stored in the browser.
 * Real secrets (WhatsApp, Gemini, Razorpay, store-publishing keys) live only as
 * Cloudflare Worker secrets and are used through lib/apiClient.ts. This wrapper keeps
 * the old code paths working while making sure such values are never written to (and any
 * old copies are removed from) localStorage. Values typed here live only in memory.
 */
const BROWSER_FORBIDDEN_KEYS = new Set<string>(["branded_apple_api_key_id", "branded_apple_private_key", "branded_google_service_account", "branded_github_token", "branded_git_ssh_private_key", "branded_git_ssh_public_key", "branded_ssh_keys"]);
const secretSafeStorage = {
    getItem(key: string): string | null {
        if (BROWSER_FORBIDDEN_KEYS.has(key)) {
            try { localStorage.removeItem(key); } catch {}
            return null;
        }
        return localStorage.getItem(key);
    },
    setItem(key: string, value: string): void {
        if (BROWSER_FORBIDDEN_KEYS.has(key)) {
            try { localStorage.removeItem(key); } catch {}
            return;
        }
        localStorage.setItem(key, value);
    },
    removeItem(key: string): void {
        localStorage.removeItem(key);
    },
};


