    const handleBiometricPreset = (preset: 'all' | 'today' | '7d' | '30d') => {
        setBiometricDatePreset(preset);
        const todayStr = new Date().toISOString().split('T')[0];
        if (preset === 'all') {
            setBiometricStartDate('');
            setBiometricEndDate('');
        } else if (preset === 'today') {
            setBiometricStartDate(todayStr);
            setBiometricEndDate(todayStr);
        } else if (preset === '7d') {
            const past = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
            setBiometricStartDate(past.toISOString().split('T')[0]);
            setBiometricEndDate(todayStr);
        } else if (preset === '30d') {
            const past = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
            setBiometricStartDate(past.toISOString().split('T')[0]);
            setBiometricEndDate(todayStr);
        }
    };

    const filteredBiometricLogs = useMemo(() => {
        let logs = biometricAuditLogs;
        if (biometricSearchFilter) {
            const lower = biometricSearchFilter.toLowerCase();
            logs = logs.filter(log => 
                log.user.toLowerCase().includes(lower) || 
                log.status.toLowerCase().includes(lower) ||
                log.details.toLowerCase().includes(lower)
            );
        }
        if (biometricStartDate) {
            const startMs = new Date(`${biometricStartDate}T00:00:00`).getTime();
            logs = logs.filter(log => {
                const logTime = new Date(log.timestamp).getTime();
                return !isNaN(logTime) && logTime >= startMs;
            });
        }
        if (biometricEndDate) {
            const endMs = new Date(`${biometricEndDate}T23:59:59.999`).getTime();
            logs = logs.filter(log => {
                const logTime = new Date(log.timestamp).getTime();
                return !isNaN(logTime) && logTime <= endMs;
            });
        }
        return logs;
    }, [biometricAuditLogs, biometricSearchFilter, biometricStartDate, biometricEndDate]);

