        localStorage.removeItem('branded_github_connected');
        localStorage.removeItem('branded_github_user');
        secretSafeStorage.removeItem('branded_github_token');
        localStorage.removeItem('branded_auto_push_github');
        localStorage.removeItem('branded_auto_trigger_branch_update');
