    // Haptic Feedback (vibration) support with navigator.vibrate compatibility check
    const hasHapticsSupport = useMemo(() => {
        return typeof window !== 'undefined' && 'navigator' in window && typeof navigator.vibrate === 'function';
    }, []);

    const triggerHapticFeedback = (type: 'success' | 'denied' | 'tap') => {
        if (typeof window !== 'undefined' && 'navigator' in window && typeof navigator.vibrate === 'function') {
            try {
                if (type === 'success') {
                    // Short, crisp pattern for success (e.g. double tap [60, 40, 60] ms)
                    navigator.vibrate([60, 40, 60]);
                } else if (type === 'denied') {
                    // Long, distinct vibration warning pattern for denied access ([250, 100, 250, 100, 350] ms)
                    navigator.vibrate([250, 100, 250, 100, 350]);
                } else if (type === 'tap') {
                    navigator.vibrate(35);
                }
            } catch (err) {
                console.debug('Haptic feedback vibration error:', err);
            }
        }
    };

    const playLowPitchBuzz = () => {
        try {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
            if (!AudioContextClass) return;
            const ctx = new AudioContextClass();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(140, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(70, ctx.currentTime + 0.25);
            gain.gain.setValueAtTime(0.18, ctx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.25);
            osc.start(ctx.currentTime);
            osc.stop(ctx.currentTime + 0.25);
        } catch (e) {
            console.error("Audio playback error:", e);
        }
    };

    const handleSimulateScanProcess = (forceResult?: 'approved' | 'denied') => {
        if (simScanStatus === 'validating') return;
        
        // Move to VALIDATING state
        setSimScanStatus('validating');
        setScanOverlaySuccess(false);
        setSimScanDetail({
            code: `FF-VIP-${Math.floor(100000 + Math.random() * 900000)}`,
            title: 'VALIDATING DIGITAL PASS',
            message: 'Validating cryptographic signature & status...',
            timestamp: new Date().toLocaleTimeString()
        });

        const isDenied = forceResult === 'denied' || (forceResult !== 'approved' && simInvalidQr);

        setTimeout(() => {
            if (isDenied) {
                setSimScanStatus('denied');
                setScanOverlaySuccess(false);
                setSimScanDetail({
                    code: 'ERR_SIG_INVALID_403',
                    title: 'ACCESS DENIED',
                    message: simInvalidQr 
                        ? 'Security Alert: Forged QR token or revoked pass' 
                        : 'Digital pass signature invalid or pass expired',
                    tier: 'Unauthorized Access',
                    timestamp: new Date().toLocaleTimeString()
                });
                const deniedVisitor = {
                    id: `vis-${Date.now()}`,
                    name: 'Guest (Invalid Pass Token)',
                    membershipTier: 'Revoked / Expired Token',
                    timestamp: 'Just now',
                    rawTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
                    gate: 'Turnstile Gate A (FastPass)',
                    status: 'denied' as const,
                    tokenHash: 'ERR_SIG_INVALID_403'
                };
                setRecentScanVisitors(prev => [deniedVisitor, ...prev.slice(0, 9)]);
                playLowPitchBuzz();
                triggerHapticFeedback('denied');
                addToast('QR Code Denied: Access rejected.', 'error');
            } else {
                setSimScanStatus('approved');
                setScanOverlaySuccess(true);
                const generatedCode = `FF-VIP-${Math.floor(100000 + Math.random() * 900000)}`;
                setSimScanDetail({
                    code: generatedCode,
                    title: 'ACCESS APPROVED',
                    message: 'HMAC-SHA256 signature verified • Turnstile unlocked',
                    tier: 'Elite VIP Champion',
                    timestamp: new Date().toLocaleTimeString()
                });
                playHighPitchBeep();
                triggerHapticFeedback('success');
                setScanHistory(prev => [new Date().toLocaleTimeString(), ...prev.slice(0, 4)]);
                setCheckInCount(prev => prev + 1);
                const approvedVisitor = {
                    id: `vis-${Date.now()}`,
                    name: 'VIP Member (Mobile Scanner)',
                    membershipTier: 'VIP Black-Card Member',
                    timestamp: 'Just now',
                    rawTime: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
                    gate: 'Turnstile Gate A (FastPass)',
                    status: 'approved' as const,
                    tokenHash: generatedCode
                };
                setRecentScanVisitors(prev => [approvedVisitor, ...prev.slice(0, 9)]);
                addToast('QR Code Approved: Access granted!', 'success');
            }
        }, 1200);
    };

